// Shared helpers for the two PDF build scripts.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
export const DOCS = path.join(ROOT, 'docs');

// Mandatory footer text for every generated PDF (exact wording).
export const FOOTER_LINES = [
  'Generated by AI. AI can make mistakes. Validate before relying upon this document.',
  '© 2026 Cotiviti, Inc. All rights reserved. All proprietary information shall remain the sole and exclusive property of Cotiviti, Inc.',
];

export function read(rel) {
  const file = path.isAbsolute(rel) ? rel : path.join(ROOT, rel);
  return fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
}

export function exists(rel) {
  return fs.existsSync(path.isAbsolute(rel) ? rel : path.join(ROOT, rel));
}

/** Shifts markdown heading levels (never beyond h6) while ignoring fenced code. */
export function shiftHeadings(md, by) {
  let fence = false;
  return md
    .split('\n')
    .map((line) => {
      if (/^```/.test(line)) fence = !fence;
      if (fence) return line;
      const m = /^(#{1,6})\s+(.*)$/.exec(line);
      if (!m) return line;
      return `${'#'.repeat(Math.min(6, m[1].length + by))} ${m[2]}`;
    })
    .join('\n');
}

/** Removes the first H1 line (the chapter title is supplied separately). */
export function dropTitle(md) {
  return md.replace(/^#\s+.*\n+/, '');
}

/** Turns "docs relative" markdown links to local .md/.mmd files into plain text (PDF has no files). */
export function stripLocalLinks(md) {
  return md.replace(/\[([^\]]+)\]\((?!https?:|#)[^)]+\.(?:md|mmd|yml|yaml|json|sh|java|ts)(?:#[^)]*)?\)/g, '$1');
}

export function diagram(n, caption, baseDir = DOCS) {
  const dir = path.join(DOCS, 'diagrams', 'rendered');
  const hit = fs.existsSync(dir) ? fs.readdirSync(dir).find((f) => f.startsWith(n) && f.endsWith('.png')) : null;
  if (!hit) return `\n_(diagram ${n} not available)_\n`;
  const rel = path.relative(baseDir, path.join(dir, hit)).replace(/\\/g, '/');
  return `\n![${caption}](${rel})\n`;
}

/**
 * Renders every inline ```mermaid block found in the sections in ONE mermaid-cli run (a browser launch per
 * diagram is very slow here) and returns a renderMermaid callback backed by that cache.
 */
export function prerenderMermaid(sections) {
  const mmdc = path.join(ROOT, '.work', 'tools', 'mermaid', 'node_modules', '.bin', 'mmdc.cmd');
  const cfg = path.join(DOCS, 'diagrams', 'puppeteer-config.json');
  const cache = path.join(ROOT, '.work', 'pdf-cache');
  fs.mkdirSync(cache, { recursive: true });
  const blocks = new Map(); // code -> hash
  for (const s of sections) {
    for (const m of (s.md ?? '').matchAll(/```mermaid\n([\s\S]*?)```/g)) {
      const code = m[1].replace(/\n+$/, '');
      blocks.set(code, crypto.createHash('sha1').update(code).digest('hex').slice(0, 16));
    }
  }
  const todo = [...blocks.entries()].filter(([, h]) => !fs.existsSync(path.join(cache, `mmd-${h}.png`)));
  if (todo.length && fs.existsSync(mmdc) && fs.existsSync(cfg)) {
    const dir = path.join(cache, 'batch');
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'all.md'), todo.map(([c]) => '```mermaid\n' + c.trimEnd() + '\n```\n').join('\n'));
    try {
      execFileSync(mmdc, ['-p', cfg, '-i', path.join(dir, 'all.md'), '-o', path.join(dir, 'all-png.md'), '-e', 'png', '-b', 'white', '-j', '2', '--size', '1800', '-s', '2'],
        { stdio: 'pipe', shell: true, timeout: 600000 });
    } catch (e) {
      console.warn('mermaid batch render reported an error');
    }
    todo.forEach(([, h], i) => {
      const produced = path.join(dir, `all-png-${i + 1}.png`);
      if (fs.existsSync(produced)) fs.copyFileSync(produced, path.join(cache, `mmd-${h}.png`));
    });
  }
  return (code) => {
    const h = blocks.get(code);
    const png = h ? path.join(cache, `mmd-${h}.png`) : null;
    return png && fs.existsSync(png) ? png : null;
  };
}

/** Returns a renderMermaid callback that renders through mermaid-cli (if installed) with an on-disk cache. */
export function mermaidRenderer() {
  const cli = path.join(ROOT, '.work', 'tools', 'mermaid', 'node_modules', '@mermaid-js', 'mermaid-cli', 'src', 'cli.js');
  const cfg = path.join(DOCS, 'diagrams', 'puppeteer-config.json');
  const cache = path.join(ROOT, '.work', 'pdf-cache');
  fs.mkdirSync(cache, { recursive: true });
  if (!fs.existsSync(cli) || !fs.existsSync(cfg)) return () => null;
  return (code) => {
    const hash = crypto.createHash('sha1').update(code).digest('hex').slice(0, 16);
    const png = path.join(cache, `mmd-${hash}.png`);
    if (fs.existsSync(png)) return png;
    const src = path.join(cache, `mmd-${hash}.mmd`);
    fs.writeFileSync(src, code);
    try {
      execFileSync(process.execPath, [cli, '-i', src, '-o', png, '-p', cfg, '-s', '2', '-w', '1600', '-b', 'white', '-q'], {
        stdio: 'pipe',
        timeout: 120000,
      });
      return fs.existsSync(png) ? png : null;
    } catch {
      return null;
    }
  };
}

/** Concatenate markdown parts, each separated by a blank line. */
export function join(...parts) {
  return parts.filter(Boolean).join('\n\n');
}

/** Rewrites image links written for GitHub (relative to the markdown file) so they resolve from the docs/ root used by the PDF engine. */
export function fixImages(md) {
  return md.replace(/\]\(\.\.\/diagrams\/rendered\//g, '](diagrams/rendered/').replace(/\]\(\.\.\/screenshots\//g, '](screenshots/');
}

/** Reads a markdown file with image links fixed and local file links turned into plain text. */
export function doc(rel) {
  return stripLocalLinks(fixImages(read(rel)));
}

/** Returns the H2 sections whose titles start with any of `titles` (each section runs to the next H2). */
export function h2(md, ...titles) {
  const lines = md.split('\n');
  const out = [];
  let take = false;
  let fence = false;
  for (const line of lines) {
    if (/^```/.test(line)) fence = !fence;
    const m = !fence && /^##\s+(.*)$/.exec(line);
    if (m) take = titles.some((t) => m[1].trim().startsWith(t));
    if (take) out.push(line);
  }
  return out.join('\n');
}

/** Turns a wide markdown table into one small two-column table per row (readable on a portrait page). */
export function tableToCards(md, titleColumns = 2) {
  const lines = md.split('\n');
  const start = lines.findIndex((l) => /^\|.*\|$/.test(l) && /^\|[\s:|-]+\|$/.test(lines[lines.indexOf(l) + 1] ?? ''));
  if (start < 0) return md;
  const cells = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
  const head = cells(lines[start]);
  const out = lines.slice(0, start);
  let i = start + 2;
  while (i < lines.length && /^\|.*\|$/.test(lines[i])) {
    const row = cells(lines[i]);
    const title = row.slice(0, titleColumns).join(' - ');
    out.push(`### ${title}`, '', '| Aspect | Evidence |', '| --- | --- |');
    for (let c = titleColumns; c < head.length; c++) out.push(`| **${head[c]}** | ${row[c] ?? ''} |`);
    out.push('');
    i++;
  }
  return [...out, ...lines.slice(i)].join('\n');
}
